entries[357719] = { ["name"] = "Banshee Wail", ["text"] = "Unlimited range\nInstant\nSylvanas lets forth a shrill scream, inflicting damage based on each targeted player's health, starting at [source value] Shadow damage at full health, increasing to 40072 Shadow damage, to players within 4 yards of each targeted player, interrupting for 6 sec .", ["unresolvedValues"] = true }
