entries[357739] = { ["name"] = "Realign Fate", ["text"] = "Instant\nFatescribe Roh-Kalo rearranges the Loom of Fates, authoring for himself a glorious new fate. While he is doing so, his damage taken is reduced by 99%.\n\nSeveral players are revealed as having Runic Affinity for the Loom's current configuration, and are capable of manipulating the position of the Loom's rings.\n\nAfter 40 sec, if the rings are not returned to their target positions, Fatescribe Roh-Kalo invokes the Darkest Destiny, killing all players." }
